package com.hbm.client.designator;
import com.hbm.client.gui.LegacyScreen;import com.hbm.item.designator.advanced.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.component.CustomData;import net.neoforged.neoforge.network.PacketDistributor;import org.lwjgl.glfw.GLFW;
/** Exact original176x178 GUI,22 eighteen-pixel controls, both source coordinate lines and local arithmetic preview. */
public final class ManualDesignatorScreen extends LegacyScreen{private static final ResourceLocation TEXTURE=ResourceLocation.parse("hbm:textures/gui/gui_designator.png");private final InteractionHand hand;private int left,top,shownX,shownZ;private final List<Control> controls=new ArrayList<>();public ManualDesignatorScreen(InteractionHand hand){super(Component.translatable("item.hbm.designator_manual"));this.hand=hand;}@Override protected void init(){super.init();left=(width-176)/2;top=(height-178)/2;shownX=shownZ=0;if(minecraft.player!=null){var stack=minecraft.player.getItemInHand(hand);if(stack.getItem() instanceof ManualDesignatorItem){var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();shownX=tag.getInt("xCoord");shownZ=tag.getInt("zCoord");}}controls.clear();int[] values={1,5,10,50,100};for(int ref=0;ref<2;ref++){for(int i=0;i<5;i++)controls.add(new Control(25+i*27,26+ref*72,i,0,ref,values[i]));for(int i=0;i<5;i++)controls.add(new Control(25+i*27,62+ref*72,5+i,1,ref,values[i]));controls.add(new Control(133,44+ref*72,10,2,ref,0));}}
 @Override public void render(GuiGraphics g,int x,int y,float partial){renderBackground(g,x,y,partial);g.blit(TEXTURE,left,top,0,0,176,178,256,256);for(var c:controls)g.blit(TEXTURE,left+c.x,top+c.y,c.hover(x-left,y-top)?194:176,c.type*18,18,18,256,256);String sx="X: "+shownX,sz="Z: "+shownZ;g.drawString(font,sx,left+88-font.width(sx)/2,top+50,4210752,false);g.drawString(font,sz,left+88-font.width(sz)/2,top+122,4210752,false);for(var c:controls)if(c.operator==2&&c.hover(x-left,y-top))g.renderTooltip(font,Component.translatable(c.reference==0?"gui.hbm.designator.current_x":"gui.hbm.designator.current_z"),x,y);}
 @Override public boolean mouseClicked(double x,double y,int button){for(var c:controls)if(c.hover(x-left,y-top)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));PacketDistributor.sendToServer(new ManualDesignatorControl(hand,c.operator,c.value,c.reference));if(c.operator==2){if(minecraft.player!=null){if(c.reference==0)shownX=(int)Math.round(minecraft.player.getX());else shownZ=(int)Math.round(minecraft.player.getZ());}}else if(c.reference==0)shownX+=c.operator==0?c.value:-c.value;else shownZ+=c.operator==0?c.value:-c.value;return true;}return super.mouseClicked(x,y,button);}@Override public boolean keyPressed(int key,int scan,int modifiers){if(key==GLFW.GLFW_KEY_ESCAPE||minecraft.options.keyInventory.matches(key,scan)){onClose();return true;}return super.keyPressed(key,scan,modifiers);}@Override public void tick(){if(minecraft.player==null||!(minecraft.player.getItemInHand(hand).getItem() instanceof ManualDesignatorItem))onClose();}private record Control(int x,int y,int type,int operator,int reference,int value){boolean hover(double mx,double my){return x<=mx&&x+18>mx&&y<my&&y+18>=my;}}}
